    2: [4],
    4: [2, 7, 11],
    7: [2, 9],
    10: [4, 7, 11]
}

common_col = 4
min_zeros, max_zeros = 2, 11

def row_pattern(zeros):
    result = [8] * cols
    for z in zeros:
        result[z] = 2
    return result

def row_endpoints(min_z, max_z):
    return [0] * min_z + [2] + [0] * (max_z - min_z - 1) + [2] + [0] * (cols - 1 - max_z)

def row_horizontal(start, end):
    return [0] * start + [2] * (end - start + 1) + [0] * (cols - 1 - end)

def row_single(col):
    return [0] * col + [2] + [0] * (cols - 1 - col)

output = []

